#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8

static int adj[MAXV][MAXV];
static int color[MAXV]; // 0 = unvisited, 1 = visiting, 2 = visited
static bool found_cycle = false;

static void dfs(int v) {
    if (found_cycle) return;          // early exit if cycle already found
    color[v] = 1;                     // mark as visiting (gray)
    for (int u = 0; u < MAXV; ++u) {
        if (adj[u][v]) {              // edge v -> u (matrix stored transposed)
            if (color[u] == 0) {
                dfs(u);
                if (found_cycle) return;
            } else if (color[u] == 1) {
                // back edge -> cycle
                found_cycle = true;
                return;
            }
        }
    }
    color[v] = 2;                     // finished (black)
}

int main(int argc, char *argv[]) {
    // The program expects an even number of arguments after the program name.
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    // Initialise adjacency matrix to 0 (already zero‑initialised globally).
    for (int i = 0; i < MAXV; ++i)
        for (int j = 0; j < MAXV; ++j)
            adj[i][j] = 0;

    // Parse edge list: each pair (src dst) represents a directed edge src -> dst.
    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long src = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 0; }
        long dst = strtol(argv[i + 1], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 0; }
        if (src < 0 || src >= MAXV || dst < 0 || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }
        // Store edge in transposed form to match the original DFS logic.
        adj[dst][src] = 1;
    }

    // Run DFS from every vertex that hasn't been visited yet.
    for (int v = 0; v < MAXV; ++v) {
        if (color[v] == 0) {
            dfs(v);
            if (found_cycle) break;
        }
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
